-- Curate topic-specific Earth, space, Moon, physics, and foundational science questions.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en, quiz_fil=v.quiz_fil, explanation_en=c.fact_en,
    explanation_fil=c.fact_fil, options=v.options::jsonb
FROM (VALUES
 ($$starter-earth-atmosphere-nitrogen$$,$$A class models the gases in dry air. Which gas makes up the largest share?$$,$$Nagmomodelo ang klase ng mga gas sa tuyong hangin. Aling gas ang may pinakamalaking bahagi?$$,$$[{"en":"Nitrogen","fil":"Nitrogen","correct":true},{"en":"Oxygen","fil":"Oxygen","correct":false},{"en":"Carbon dioxide","fil":"Carbon dioxide","correct":false},{"en":"Hydrogen","fil":"Hydrogen","correct":false}]$$),
 ($$starter-earth-atmosphere-oxygen$$,$$A student compares the main gases in air. Which gas is about one-fifth of Earth’s atmosphere and is used in respiration?$$,$$Inihahambing ng mag-aaral ang pangunahing gas sa hangin. Aling gas ang humigit-kumulang ikalimang bahagi ng atmospera at ginagamit sa respiration?$$,$$[{"en":"Oxygen","fil":"Oxygen","correct":true},{"en":"Nitrogen","fil":"Nitrogen","correct":false},{"en":"Argon","fil":"Argon","correct":false},{"en":"Carbon dioxide","fil":"Carbon dioxide","correct":false}]$$),
 ($$starter-earth-atmosphere-protect$$,$$Many small space rocks burn before reaching the ground. Which Earth system helps shield life from some incoming radiation and small meteoroids?$$,$$Nasusunog bago bumagsak sa lupa ang maraming maliliit na bato mula sa kalawakan. Aling sistema ng Daigdig ang tumutulong sumangga sa ilang radiation at meteoroid?$$,$$[{"en":"The atmosphere","fil":"Ang atmospera","correct":true},{"en":"The inner core","fil":"Ang panloob na ubod","correct":false},{"en":"The ocean floor","fil":"Ang ilalim ng karagatan","correct":false},{"en":"The Moon’s far side","fil":"Ang likod ng Buwan","correct":false}]$$),
 ($$starter-earth-hemispheres$$,$$Earth’s tilted axis makes seasons opposite in the Northern and Southern Hemispheres. When it is summer in one, what season is generally occurring in the other?$$,$$Dahil sa pagkakahilig ng aksis ng Daigdig, magkasalungat ang mga panahon sa Hilaga at Timog na Hemispero. Anong panahon ang karaniwang nararanasan sa kabila kapag tag-init sa isa?$$,$$[{"en":"Winter","fil":"Taglamig","correct":true},{"en":"Summer","fil":"Tag-init","correct":false},{"en":"The same season everywhere","fil":"Parehong panahon sa lahat ng lugar","correct":false},{"en":"No season","fil":"Walang panahon","correct":false}]$$),
 ($$starter-earth-moon-count$$,$$A planetarium asks how many natural moons orbit Earth. What should the presenter answer?$$,$$Itinanong sa planetarium kung ilang likas na buwan ang umiikot sa Daigdig. Ano ang dapat isagot ng tagapagsalita?$$,$$[{"en":"One","fil":"Isa","correct":true},{"en":"Two","fil":"Dalawa","correct":false},{"en":"Four","fil":"Apat","correct":false},{"en":"Eight","fil":"Walo","correct":false}]$$),
 ($$starter-earth-rocky$$,$$An astronomer classifies Earth by its solid surface and composition. Which planet group does Earth belong to?$$,$$Inuuri ng astronomo ang Daigdig batay sa matigas nitong ibabaw at komposisyon. Sa aling pangkat ng planeta kabilang ang Daigdig?$$,$$[{"en":"The terrestrial, rocky planets","fil":"Mga terrestrial o batong planeta","correct":true},{"en":"The gas giants","fil":"Mga higanteng gas","correct":false},{"en":"The ice giants only","fil":"Mga higanteng yelo lamang","correct":false},{"en":"Dwarf planets","fil":"Mga dwarf planet","correct":false}]$$),
 ($$starter-earth-rotation$$,$$A globe is lit from one side by a lamp representing the Sun. What movement makes different places on Earth experience day and night?$$,$$Sinisinagan ng lampara ang isang panig ng globo bilang Araw. Anong galaw ang nagdudulot ng araw at gabi sa iba’t ibang lugar sa Daigdig?$$,$$[{"en":"Earth rotating on its axis","fil":"Pag-ikot ng Daigdig sa aksis nito","correct":true},{"en":"Earth orbiting the Moon","fil":"Pag-ikot ng Daigdig sa Buwan","correct":false},{"en":"The Sun orbiting Earth each day","fil":"Pag-ikot ng Araw sa Daigdig araw-araw","correct":false},{"en":"Clouds moving over continents","fil":"Pagdaan ng mga ulap sa mga kontinente","correct":false}]$$),
 ($$starter-earth-satellite$$,$$A weather agency uses an artificial object orbiting Earth to observe clouds. What is this object?$$,$$Gumagamit ang ahensiya ng panahon ng gawang-taong bagay na umiikot sa Daigdig upang obserbahan ang mga ulap. Ano ito?$$,$$[{"en":"An artificial satellite","fil":"Artipisyal na satellite","correct":true},{"en":"A meteorite","fil":"Meteorite","correct":false},{"en":"A natural moon","fil":"Likas na buwan","correct":false},{"en":"A comet tail","fil":"Buntot ng kometa","correct":false}]$$),
 ($$starter-earth-seasons$$,$$Earth is closest to the Sun during part of its orbit, yet seasons are not caused simply by distance. What is the main cause?$$,$$Pinakamalapit sa Araw ang Daigdig sa isang bahagi ng orbit nito, ngunit hindi simpleng layo ang sanhi ng mga panahon. Ano ang pangunahing sanhi?$$,$$[{"en":"Earth’s tilted axis as it orbits the Sun","fil":"Pagkahilig ng aksis ng Daigdig habang umiikot ito sa Araw","correct":true},{"en":"The Moon’s changing shape","fil":"Pagbabago ng hugis ng Buwan","correct":false},{"en":"Earth’s daily rotation alone","fil":"Araw-araw na pag-ikot lamang ng Daigdig","correct":false},{"en":"Changes in ocean salinity","fil":"Pagbabago ng alat ng karagatan","correct":false}]$$),
 ($$starter-earth-water-surface$$,$$Satellite images show most of Earth’s surface covered by water. About what fraction is covered by oceans and other water?$$,$$Ipinakikita ng satellite image na tubig ang malaking bahagi ng ibabaw ng Daigdig. Humigit-kumulang anong bahagi nito ang natatakpan ng karagatan at iba pang tubig?$$,$$[{"en":"About 71 percent","fil":"Humigit-kumulang 71 porsiyento","correct":true},{"en":"About 10 percent","fil":"Humigit-kumulang 10 porsiyento","correct":false},{"en":"About 30 percent","fil":"Humigit-kumulang 30 porsiyento","correct":false},{"en":"About 95 percent","fil":"Humigit-kumulang 95 porsiyento","correct":false}]$$),
 ($$starter-earth-year$$,$$A calendar tracks one complete trip of Earth around the Sun. About how long is one Earth year?$$,$$Sinusubaybayan ng kalendaryo ang isang buong pag-ikot ng Daigdig sa Araw. Gaano katagal ang isang taon sa Daigdig?$$,$$[{"en":"About 365 days","fil":"Humigit-kumulang 365 araw","correct":true},{"en":"About 24 hours","fil":"Humigit-kumulang 24 oras","correct":false},{"en":"About 30 days","fil":"Humigit-kumulang 30 araw","correct":false},{"en":"About 12 hours","fil":"Humigit-kumulang 12 oras","correct":false}]$$),
 ($$starter-earth-orbit$$,$$A planet continues moving around the Sun because the Sun’s gravity bends its path. What is this repeated path called?$$,$$Patuloy na umiikot ang planeta sa Araw dahil binabaluktot ng grabidad ng Araw ang landas nito. Ano ang tawag sa paulit-ulit na landas?$$,$$[{"en":"An orbit","fil":"Orbit","correct":true},{"en":"A rotation axis","fil":"Aksis ng pag-ikot","correct":false},{"en":"A latitude line","fil":"Guhit ng latitude","correct":false},{"en":"A shadow cone","fil":"Kono ng anino","correct":false}]$$),
 ($$starter-solar-milky-way$$,$$The Sun is one star among billions. What larger structure contains our Solar System?$$,$$Isa ang Araw sa bilyun-bilyong bituin. Anong mas malaking estruktura ang kinalalagyan ng ating Solar System?$$,$$[{"en":"The Milky Way galaxy","fil":"Kalawakang Milky Way","correct":true},{"en":"The Andromeda system only","fil":"Andromeda lamang","correct":false},{"en":"Earth’s atmosphere","fil":"Atmospera ng Daigdig","correct":false},{"en":"The asteroid belt","fil":"Asteroid belt","correct":false}]$$),
 ($$starter-solar-sun-star$$,$$A learner compares the Sun with other stars seen at night. What is the Sun?$$,$$Inihahambing ng mag-aaral ang Araw sa mga bituing nakikita sa gabi. Ano ang Araw?$$,$$[{"en":"A star that is closest to Earth","fil":"Bituing pinakamalapit sa Daigdig","correct":true},{"en":"A planet reflecting another star’s light","fil":"Planeta na sumasalamin sa liwanag ng ibang bituin","correct":false},{"en":"A moon orbiting Earth","fil":"Buwang umiikot sa Daigdig","correct":false},{"en":"A galaxy made of planets","fil":"Kalawakang binubuo ng mga planeta","correct":false}]$$),
 ($$starter-solar-planets-eight$$,$$A Solar System model counts the planets recognized in the main planetary group. How many are there?$$,$$Binibilang sa modelo ng Solar System ang mga kinikilalang planeta sa pangunahing pangkat. Ilan ang mga ito?$$,$$[{"en":"Eight","fil":"Walo","correct":true},{"en":"Seven","fil":"Pito","correct":false},{"en":"Nine","fil":"Siyam","correct":false},{"en":"Twelve","fil":"Labindalawa","correct":false}]$$),
 ($$starter-solar-mercury-nearest$$,$$Which planet would a spacecraft reach first when traveling outward from the Sun?$$,$$Aling planeta ang unang madaraanan ng spacecraft habang naglalakbay palayo sa Araw?$$,$$[{"en":"Mercury","fil":"Mercury","correct":true},{"en":"Venus","fil":"Venus","correct":false},{"en":"Earth","fil":"Daigdig","correct":false},{"en":"Mars","fil":"Mars","correct":false}]$$),
 ($$starter-solar-venus-hottest$$,$$Venus is farther from the Sun than Mercury, yet its surface is hotter. What explains this?$$,$$Mas malayo sa Araw ang Venus kaysa Mercury ngunit mas mainit ang ibabaw nito. Ano ang nagpapaliwanag dito?$$,$$[{"en":"Its thick carbon-dioxide atmosphere traps heat strongly.","fil":"Malakas na nagkukulong ng init ang makapal nitong atmosperang carbon dioxide.","correct":true},{"en":"It is much closer to the Sun than Mercury.","fil":"Mas malapit ito sa Araw kaysa Mercury.","correct":false},{"en":"It has no atmosphere.","fil":"Wala itong atmospera.","correct":false},{"en":"Its surface is heated by oceans.","fil":"Pinaiinit ng karagatan ang ibabaw nito.","correct":false}]$$),
 ($$starter-solar-earth-third$$,$$A model orders planets outward from the Sun. At which position is Earth?$$,$$Inaayos ng modelo ang mga planeta palayo sa Araw. Pang-ilan ang Daigdig?$$,$$[{"en":"Third","fil":"Ikatlo","correct":true},{"en":"First","fil":"Una","correct":false},{"en":"Second","fil":"Ikalawa","correct":false},{"en":"Fourth","fil":"Ikaapat","correct":false}]$$),
 ($$starter-solar-mars-red$$,$$A rover explores the planet often called the Red Planet. Which planet is it?$$,$$Sinaliksik ng rover ang planetang tinatawag na Pulang Planeta. Aling planeta ito?$$,$$[{"en":"Mars","fil":"Mars","correct":true},{"en":"Mercury","fil":"Mercury","correct":false},{"en":"Venus","fil":"Venus","correct":false},{"en":"Neptune","fil":"Neptune","correct":false}]$$),
 ($$starter-solar-jupiter-largest$$,$$Which planet has the greatest diameter in our Solar System?$$,$$Aling planeta ang may pinakamalaking diyametro sa Solar System?$$,$$[{"en":"Jupiter","fil":"Jupiter","correct":true},{"en":"Saturn","fil":"Saturn","correct":false},{"en":"Earth","fil":"Daigdig","correct":false},{"en":"Neptune","fil":"Neptune","correct":false}]$$),
 ($$starter-solar-jupiter-storm$$,$$Astronomers track a long-lasting giant storm on Jupiter. What is it called?$$,$$Sinusubaybayan ng mga astronomo ang matagal nang higanteng bagyo sa Jupiter. Ano ang tawag dito?$$,$$[{"en":"The Great Red Spot","fil":"Great Red Spot","correct":true},{"en":"The Great Dark Rift","fil":"Great Dark Rift","correct":false},{"en":"The Solar Flare","fil":"Solar flare","correct":false},{"en":"The Eye of Saturn","fil":"Mata ng Saturn","correct":false}]$$),
 ($$starter-solar-saturn-rings$$,$$Which planet is especially known for its broad, bright ring system?$$,$$Aling planeta ang kilala sa malapad at maningning na sistema ng singsing?$$,$$[{"en":"Saturn","fil":"Saturn","correct":true},{"en":"Mars","fil":"Mars","correct":false},{"en":"Mercury","fil":"Mercury","correct":false},{"en":"Earth","fil":"Daigdig","correct":false}]$$),
 ($$starter-solar-uranus-tilt$$,$$Uranus rotates with an extreme axial tilt, appearing to roll along its orbit. What makes it unusual?$$,$$Umiikot ang Uranus na may napakalaking pagkakahilig ng aksis kaya tila gumugulong sa orbit. Ano ang di-pangkaraniwan dito?$$,$$[{"en":"Its axis is tilted nearly onto its side.","fil":"Halos nakatagilid sa gilid ang aksis nito.","correct":true},{"en":"It has no orbit around the Sun.","fil":"Wala itong orbit sa Araw.","correct":false},{"en":"It is the largest planet.","fil":"Ito ang pinakamalaking planeta.","correct":false},{"en":"It is the only planet with moons.","fil":"Ito lamang ang planetang may buwan.","correct":false}]$$),
 ($$starter-solar-neptune-farthest$$,$$Which of the eight planets is farthest from the Sun?$$,$$Alin sa walong planeta ang pinakamalayo sa Araw?$$,$$[{"en":"Neptune","fil":"Neptune","correct":true},{"en":"Uranus","fil":"Uranus","correct":false},{"en":"Saturn","fil":"Saturn","correct":false},{"en":"Jupiter","fil":"Jupiter","correct":false}]$$),
 ($$starter-solar-dwarf-pluto$$,$$Pluto is round and orbits the Sun, but it has not cleared its orbital neighborhood. How is it classified?$$,$$Bilog ang Pluto at umiikot sa Araw ngunit hindi nito nalinis ang paligid ng orbit nito. Paano ito inuuri?$$,$$[{"en":"A dwarf planet","fil":"Dwarf planet","correct":true},{"en":"A major planet","fil":"Pangunahing planeta","correct":false},{"en":"A moon of Neptune","fil":"Buwan ng Neptune","correct":false},{"en":"A comet","fil":"Kometa","correct":false}]$$),
 ($$starter-solar-orbits$$,$$A student traces Earth’s path around the Sun. Which shape best approximates this orbit?$$,$$Sinusundan ng mag-aaral ang landas ng Daigdig sa paligid ng Araw. Anong hugis ang pinakamalapit dito?$$,$$[{"en":"An ellipse, which is nearly circular","fil":"Ellipse na halos bilog","correct":true},{"en":"A perfect square","fil":"Perpektong parisukat","correct":false},{"en":"A straight line","fil":"Tuwid na linya","correct":false},{"en":"A spiral into the Sun","fil":"Spiral papasok sa Araw","correct":false}]$$),
 ($$starter-solar-gravity$$,$$Planets remain in orbit instead of flying straight away from the Sun. Which force keeps them bound to it?$$,$$Nananatili sa orbit ang mga planeta sa halip na dumiretso palayo sa Araw. Anong puwersa ang nagpapanatili sa kanila rito?$$,$$[{"en":"Gravity","fil":"Grabidad","correct":true},{"en":"Friction with space","fil":"Friction sa kalawakan","correct":false},{"en":"Sound waves","fil":"Sound wave","correct":false},{"en":"Magnetism alone","fil":"Magnetismo lamang","correct":false}]$$),
 ($$starter-moon-reflects$$,$$The Moon appears bright at night. What is the source of the light we see?$$,$$Maliwanag ang Buwan sa gabi. Ano ang pinagmumulan ng liwanag na nakikita natin?$$,$$[{"en":"Sunlight reflected from the Moon’s surface","fil":"Sikat ng Araw na sinasalamin ng ibabaw ng Buwan","correct":true},{"en":"Light produced by fires on the Moon","fil":"Liwanag mula sa apoy sa Buwan","correct":false},{"en":"The Moon’s own starlight","fil":"Sariling liwanag-bituin ng Buwan","correct":false},{"en":"Earth’s core glowing through it","fil":"Liwanag ng ubod ng Daigdig na tumatagos dito","correct":false}]$$),
 ($$starter-moon-phases$$,$$Over several weeks, the Moon’s visible lit shape changes. What causes the phases?$$,$$Nagbabago sa loob ng ilang linggo ang nakikitang maliwanag na bahagi ng Buwan. Ano ang sanhi ng mga phase?$$,$$[{"en":"We see different portions of the Moon’s sunlit half as it orbits Earth.","fil":"Magkakaibang bahagi ng kalahating sinisinagan ng Araw ang nakikita habang umiikot ang Buwan sa Daigdig.","correct":true},{"en":"Earth’s shadow covers it every night.","fil":"Tinatakpan ito ng anino ng Daigdig gabi-gabi.","correct":false},{"en":"The Moon changes its physical shape.","fil":"Nagbabago ang pisikal na hugis ng Buwan.","correct":false},{"en":"Clouds permanently block part of it.","fil":"Palaging hinaharangan ng ulap ang bahagi nito.","correct":false}]$$),
 ($$starter-moon-orbit$$,$$A month-long observation follows the Moon as it travels around Earth. What is the Moon doing?$$,$$Sinusubaybayan sa loob ng isang buwan ang paglalakbay ng Buwan sa paligid ng Daigdig. Ano ang ginagawa nito?$$,$$[{"en":"Orbiting Earth","fil":"Umiikot sa Daigdig","correct":true},{"en":"Orbiting the Sun without Earth","fil":"Umiikot sa Araw nang hindi kasabay ng Daigdig","correct":false},{"en":"Rotating around Mars","fil":"Umiikot sa Mars","correct":false},{"en":"Staying fixed above one location","fil":"Nananatiling nakapirmi sa ibabaw ng iisang lugar","correct":false}]$$),
 ($$starter-moon-craters$$,$$A lunar image shows circular pits left by impacts. What most commonly formed these craters?$$,$$Ipinakikita ng larawan ng Buwan ang mga bilog na hukay mula sa impact. Ano ang karaniwang lumikha sa mga crater?$$,$$[{"en":"Impacts from asteroids and meteoroids","fil":"Pagbangga ng mga asteroid at meteoroid","correct":true},{"en":"Rain and flowing rivers","fil":"Ulan at umaagos na ilog","correct":false},{"en":"Wind erosion","fil":"Pagguho dahil sa hangin","correct":false},{"en":"Volcanic ash carried by oceans","fil":"Abong bulkan na tinangay ng karagatan","correct":false}]$$),
 ($$starter-moon-tides$$,$$Ocean tides rise and fall in a regular pattern. Which nearby object’s gravity is the main influence?$$,$$Regular na tumataas at bumababa ang tubig-dagat. Grabidad ng aling kalapit na bagay ang pangunahing nakaaapekto rito?$$,$$[{"en":"The Moon","fil":"Buwan","correct":true},{"en":"Mars","fil":"Mars","correct":false},{"en":"A nearby mountain","fil":"Kalapit na bundok","correct":false},{"en":"A passing airplane","fil":"Dumaraang eroplano","correct":false}]$$),
 ($$starter-moon-satellite$$,$$Earth has one natural satellite. Which object is it?$$,$$May isang likas na satellite ang Daigdig. Aling bagay ito?$$,$$[{"en":"The Moon","fil":"Ang Buwan","correct":true},{"en":"The Sun","fil":"Araw","correct":false},{"en":"Mars","fil":"Mars","correct":false},{"en":"The Milky Way","fil":"Milky Way","correct":false}]$$),
 ($$starter-moon-size$$,$$Compared with Earth, how wide is the Moon approximately?$$,$$Kung ihahambing sa Daigdig, gaano kalapad ang Buwan?$$,$$[{"en":"About one-quarter of Earth’s diameter","fil":"Humigit-kumulang sangkapat ng diyametro ng Daigdig","correct":true},{"en":"About the same diameter","fil":"Halos kapareho ng diyametro","correct":false},{"en":"About twice Earth’s diameter","fil":"Humigit-kumulang doble ng diyametro","correct":false},{"en":"About the size of a city","fil":"Kaslaki lamang ng isang lungsod","correct":false}]$$),
 ($$starter-gravity$$,$$A dropped ball falls toward the ground instead of drifting away. Which force causes this attraction?$$,$$Bumabagsak sa lupa ang binitawang bola sa halip na lumutang palayo. Aling puwersa ang sanhi ng hatak na ito?$$,$$[{"en":"Gravity between Earth and the ball","fil":"Grabidad sa pagitan ng Daigdig at bola","correct":true},{"en":"Buoyancy from air alone","fil":"Buoyancy mula lamang sa hangin","correct":false},{"en":"Magnetism in every object","fil":"Magnetismo sa lahat ng bagay","correct":false},{"en":"Friction with sunlight","fil":"Friction sa sikat ng araw","correct":false}]$$),
 ($$starter-ice-density$$,$$Ice floats in liquid water. Which property explains this observation?$$,$$Lumulutang ang yelo sa likidong tubig. Aling katangian ang nagpapaliwanag nito?$$,$$[{"en":"Ice is less dense than liquid water.","fil":"Mas mababa ang densidad ng yelo kaysa likidong tubig.","correct":true},{"en":"Ice has greater density than water.","fil":"Mas mataas ang densidad ng yelo.","correct":false},{"en":"Ice contains no molecules.","fil":"Walang molekula ang yelo.","correct":false},{"en":"Water has no mass.","fil":"Walang masa ang tubig.","correct":false}]$$),
 ($$starter-moonlight$$,$$A student sees the Moon shining but knows it is not a star. What best explains its brightness?$$,$$Nakikita ng mag-aaral na kumikinang ang Buwan ngunit alam niyang hindi ito bituin. Ano ang nagpapaliwanag sa liwanag nito?$$,$$[{"en":"It reflects light from the Sun.","fil":"Sinasalamin nito ang liwanag mula sa Araw.","correct":true},{"en":"It produces sunlight by fusion.","fil":"Lumilikha ito ng sikat ng araw sa pamamagitan ng fusion.","correct":false},{"en":"It is made of glowing gas.","fil":"Binubuo ito ng kumikinang na gas.","correct":false},{"en":"Earth’s city lights power it.","fil":"Pinaiilaw ito ng mga ilaw ng lungsod sa Daigdig.","correct":false}]$$),
 ($$starter-ocean-water$$,$$A sample collected far offshore tastes salty. Which dissolved substance mainly gives seawater its salinity?$$,$$Maalat ang sample na kinuha sa malayong bahagi ng dagat. Anong natunaw na sangkap ang pangunahing nagbibigay ng alat sa tubig-dagat?$$,$$[{"en":"Dissolved salts, especially sodium chloride","fil":"Mga natunaw na asin, lalo na sodium chloride","correct":true},{"en":"Pure glucose","fil":"Purong glucose","correct":false},{"en":"Oxygen gas only","fil":"Oxygen gas lamang","correct":false},{"en":"Freshwater ice","fil":"Yelo mula sa tabang tubig","correct":false}]$$),
 ($$starter-photosynthesis$$,$$A plant grows near a sunny window and makes sugars in its leaves. Which process uses light energy to do this?$$,$$Tumubo ang halaman malapit sa maaraw na bintana at gumagawa ng asukal sa mga dahon. Aling proseso ang gumagamit ng liwanag?$$,$$[{"en":"Photosynthesis","fil":"Photosynthesis","correct":true},{"en":"Cellular respiration only","fil":"Cellular respiration lamang","correct":false},{"en":"Evaporation","fil":"Evaporation","correct":false},{"en":"Condensation","fil":"Condensation","correct":false}]$$),
 ($$starter-sound-vibrations$$,$$A guitar string is plucked and the sound stops when the string is held still. What produced the sound?$$,$$Pinitik ang kuwerdas ng gitara at tumigil ang tunog nang pigilan ito. Ano ang lumikha ng tunog?$$,$$[{"en":"Vibrations of the string","fil":"Panginginig ng kuwerdas","correct":true},{"en":"The string’s color","fil":"Kulay ng kuwerdas","correct":false},{"en":"Still air with no movement","fil":"Hindi gumagalaw na hangin","correct":false},{"en":"Light reflecting from the guitar","fil":"Liwanag na nasasalamin sa gitara","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,options)
WHERE c.content_key=v.content_key;
